package com.nexusdrive.common.security; import static org.junit.jupiter.api.Assertions.*; import com.nexusdrive.common.config.JwtProperties; import java.util.UUID; import org.junit.jupiter.api.Test; class JwtTokenProviderTest {@Test void createsAndParses(){var p=new JwtProperties();p.setSecret("01234567890123456789012345678901");var j=new JwtTokenProvider(p);var id=UUID.randomUUID();String t=j.generateAccessToken(id,"user","USER");assertTrue(j.validate(t));assertEquals(id,j.userId(t));assertEquals("USER",j.role(t));assertNotNull(j.parse(t).getId());}@Test void tokensIssuedInSameSecondAreUnique(){var p=new JwtProperties();p.setSecret("01234567890123456789012345678901");var j=new JwtTokenProvider(p);var id=UUID.randomUUID();assertNotEquals(j.generateRefreshToken(id,"user","USER"),j.generateRefreshToken(id,"user","USER"));}}
